import {useEffect,useState} from 'react';
import {ClipboardList,Loader2,Plus} from 'lucide-react';
import {createForm,listFormAssignments,listForms,publishForm} from '../../lib/practiceOperationsApi';
const TYPES=['SHORT_TEXT','LONG_TEXT','NUMBER','DATE','TIME','YES_NO','SINGLE_SELECT','MULTI_SELECT','CHECKBOX','RATING_SCALE','NUMERIC_SCALE','EMAIL','PHONE','FILE_UPLOAD','SECTION_INFO','CONSENT_CHECKBOX','BODY_REGION','REPEAT_GROUP'];
const blank=()=>({title:'',form_type:'CUSTOM',settings:{},sections:[{key:'section_1',title:'New section',description:'',fields:[]}]});
export function ExternalForms(){const [tab,setTab]=useState('My Forms'),[forms,setForms]=useState([]),[assignments,setAssignments]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[builder,setBuilder]=useState(false),[draft,setDraft]=useState(blank());async function load(){setState('loading');setError('');try{const [a,b]=await Promise.all([listForms(),listFormAssignments()]);setForms(a.items||[]);setAssignments(b.items||[]);setState('ready')}catch(e){setError(e.message);setState('error')}}useEffect(()=>{void load()},[]);async function save(){try{await createForm(draft);setBuilder(false);setDraft(blank());await load()}catch(e){setError(e.message)}}if(state==='loading')return <div role="status" className="grid min-h-64 place-items-center"><Loader2 className="animate-spin"/><span className="sr-only">Loading forms</span></div>;return <section className="space-y-5"><header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Practice</p><h2 className="text-3xl font-bold">Forms</h2><p className="mt-2 text-sm text-slate-600">Versioned forms, assignments, and governed responses.</p></div><button onClick={()=>setBuilder(true)} className="min-h-11 rounded-xl bg-blue-700 px-4 font-bold text-white"><Plus className="mr-1 inline" size={17}/>New form</button></header>{error&&<div role="alert" className="rounded-xl bg-rose-50 p-4 text-rose-800">{error}</div>}<nav aria-label="Form views" className="flex gap-2 overflow-x-auto">{['Templates','My Forms','Assigned Forms','Responses'].map(x=><button key={x} onClick={()=>setTab(x)} aria-pressed={tab===x} className={`min-h-11 shrink-0 rounded-xl px-4 font-semibold ${tab===x?'bg-slate-950 text-white':'border bg-white'}`}>{x}</button>)}</nav>{tab==='Assigned Forms'||tab==='Responses'?<Cards items={assignments.filter(x=>tab==='Assigned Forms'||x.status==='COMPLETED')} assignment/>:<Cards items={forms}/>} {builder&&<Builder draft={draft} setDraft={setDraft} onClose={()=>setBuilder(false)} onSave={save}/>}</section>}
function Cards({items,assignment}){return items.length?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{items.map(item=><article key={item.id} className="rounded-2xl border bg-white p-5"><ClipboardList className="text-blue-700"/><h3 className="mt-4 font-bold">{item.title}</h3><p className="mt-1 text-sm text-slate-500">{(item.form_type||'Form').replaceAll('_',' ')} · {item.status}</p>{!assignment&&item.status==='DRAFT'&&<button onClick={async()=>{await publishForm(item.id);location.reload()}} className="mt-4 min-h-11 rounded-xl border px-4 font-bold">Publish</button>}</article>)}</div>:<div className="rounded-2xl border border-dashed bg-white p-9 text-center"><h3 className="font-bold">No forms in this view</h3><p className="mt-1 text-sm text-slate-500">Confirmed empty. No failure was converted to zero.</p></div>}
function Builder({draft,setDraft,onClose,onSave}){const section=draft.sections[0];const add=()=>setDraft({...draft,sections:[{...section,fields:[...section.fields,{key:`question_${section.fields.length+1}`,label:'New question',field_type:'SHORT_TEXT',required:false,config:{},condition:null}]}]});return <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/55 p-3 sm:p-8"><section role="dialog" aria-modal="true" aria-labelledby="form-builder-title" className="mx-auto max-w-3xl rounded-3xl bg-white p-5"><div className="flex justify-between"><h2 id="form-builder-title" className="text-2xl font-bold">Form builder</h2><button aria-label="Close form builder" onClick={onClose} className="h-11 w-11 rounded-xl border">×</button></div><label className="mt-5 block font-semibold">Title<input value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label><label className="mt-4 block font-semibold">Section name<input value={section.title} onChange={e=>setDraft({...draft,sections:[{...section,title:e.target.value}]})} className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label><div className="mt-5 space-y-3">{section.fields.map((field,i)=><div key={field.key} className="grid gap-2 rounded-xl border p-3 sm:grid-cols-[1fr_180px_auto]"><input aria-label={`Question ${i+1}`} value={field.label} onChange={e=>{const fields=[...section.fields];fields[i]={...field,label:e.target.value};setDraft({...draft,sections:[{...section,fields}]})}} className="min-h-11 rounded-lg border px-3"/><select aria-label={`Question type ${i+1}`} value={field.field_type} onChange={e=>{const fields=[...section.fields];fields[i]={...field,field_type:e.target.value};setDraft({...draft,sections:[{...section,fields}]})}} className="min-h-11 rounded-lg border px-2">{TYPES.map(x=><option key={x}>{x}</option>)}</select><label className="flex min-h-11 items-center gap-2"><input type="checkbox" checked={field.required} onChange={e=>{const fields=[...section.fields];fields[i]={...field,required:e.target.checked};setDraft({...draft,sections:[{...section,fields}]})}}/>Required</label></div>)}</div><button onClick={add} className="mt-4 min-h-11 rounded-xl border px-4 font-bold">Add question</button><div className="mt-7 flex justify-end gap-2"><button onClick={onClose} className="min-h-11 rounded-xl border px-4">Cancel</button><button disabled={!draft.title||!section.fields.length} onClick={onSave} className="min-h-11 rounded-xl bg-blue-700 px-4 font-bold text-white disabled:opacity-40">Save draft</button></div></section></div>}
